def longest_consecutive_streak(items: list[int]) -> int:
    if len(items) == 0:
        return 0
    max_streak = 0
    current_streak = 1
    for i in range(1, len(items)):
        if items[i] == items[i-1]:
            current_streak += 1
        else:
            max_streak = max(max_streak, current_streak)
            current_streak = 1
    max_streak = max(max_streak, current_streak)
    return max_streak

