def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    current_token = ""
    for char in source:
        if char == ' ':
            if current_token:
                tokens.append((current_token, char))
                current_token = ""
        elif char.islower():
            current_token += char
        else:
            current_token += char
    if current_token:
        tokens.append((current_token, char))
    return tokens

