    """
    এই ফাংশনটি নির্দিষ্ট edges এর মধ্যে সমস্ত সম্ভাব্য সংযোগ খুঁজে বের করে।
    এটি একটি ডাইনামিক প্রোগ্রামিং পদ্ধতি ব্যবহার করে, যেখানে আমরা একটি হ্যাশ ম্যাপ তৈরি করি যাতে প্রতিটি নোডের সাথে সংযুক্ত অন্যান্য নোডের সংখ্যা ট্র্যাক করা হয়।
    তারপর, আমরা প্রতিটি নোডের জন্য, আমরা তার সংযুক্ত নোডের সংখ্যা গণনা করি এবং যদি এটি 1 এর বেশি হয়, তাহলে আমরা সেই সংযোগটি একটি সংযোগের তালিকায় যোগ করি।
    অবশেষে, আমরা সেই সংযোগের তালিকা ফেরত দিই।
    """
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = set()
        if v not in graph:
            graph[v] = set()
        graph[u].add(v)
        graph[v].add(u)
    bridges = []
    for u, v in graph.items():
        if len(v) == 1:
            bridges.append((u, v))
    return bridges

