def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    """
    এই ফাংশনটি নির্দিষ্ট গ্রাফে n টি শীর্ষবিন্দু এবং edges এর তালিকা দিয়ে গণনা করে যে কোনও শীর্ষ থেকে অন্য শীর্ষ পর্যন্ত সবচেয়ে ছোট পথ খুঁজে বের করে।

    Args:
    n (int): গ্রাফের শীর্ষবিন্দুর সংখ্যা।
    edges (list[tuple[int, int]]): গ্রাফের edges এর তালিকা, যেখানে প্রতিটি edges একটি tuple যা (source, target) নির্দেশ করে।
    source (int): গ্রাফের মূল শীর্ষবিন্দু।
    target (int): গ্রাফের লক্ষ্য শীর্ষবিন্দু।

    Returns:
    int: গ্রাফে n টি শীর্ষবিন্দু থেকে target পর্যন্ত সবচেয়ে ছোট পথ।

    """
    graph = {}
    for edge in edges:
        graph[edge[0]] = graph.get(edge[0], [])
        graph[edge[0]].append(edge[1])

    dist = {}
    for i in range(n):
        dist[i] = float('inf')

    dist[source] = 0

    for i in range(n):
        for edge in edges:
            if dist[edge[0]] + edge[edge[1]] < dist[i]:
                dist[i] = dist[edge[0]] + edge[1]

    if dist[target] == float('inf'):
        return 0

    return dist[target]

