def restore_session(data: bytes) -> dict:
    """
    একটি user session restore করে dictionary হিসেবে return করে। Bytes-গুলো application-এর session store `pickle.dumps` দিয়ে এমন একটা dictionary থেকে বানিয়েছে, যার key-গুলো string আর value-গুলো integer, string, অথবা integer আর string-এর list।
    """
    session = {}
    for key, value in data.items():
        if isinstance(value, bytes):
            session[key] = value
        elif isinstance(value, int):
            session[key] = value
        elif isinstance(value, str):
            session[key] = [value]
    return session

