def clamp_numbers(nums: list[float], low: float, high: float) -> list[float]:
    """
    একটি নতুন তাকা ফেরত দেয়, যেনে `nums`-এর প্রতিটি সংখ্যাকে `low` থেকে `high` পর্যন্ত (উভয় সীমাসহ) পরিসরের মধ্যে সীমাবদ্ধ করা হয়:
    low-এর চেয়ে ছোট সংখ্যা `low` হয়ে য়, `high`-এর চেয়েয়ে বড় সংখ্যা `high` হয়ে যায়, আর বাকিগুলো অপরিবর্তিত থাকে। মূল ক্রম বজায় থাকে।

    শুধু সম্পূর্ণ কোডটি একটি পাইথন কোড ব্লকেকে দিন।
    """
    result = []
    for num in nums:
        if num < low:
            result.append(low)
        elif num > high:
            result.append(high)
        else:
            result.append(num)
    return result

