    - बाकी संख्याएँ जो सीमा में नहीं हैं
    - मूल सूची को संरक्षित रखता है।
    """
    result = []
    for num in nums:
        if low <= num <= high:
            result.append(num)
        elif num < low:
            result.append(low)
        elif num > high:
            result.append(high)
        else:
            result.append(num)
    return result

