def parse_config(text: str) -> dict:
    config = {}
    lines = text.splitlines()
    current_node = {}
    for line in lines:
        if line.startswith("---"):
            current_node["type"] = line[1:-1]
            continue
        if current_node["type"] == "dict":
            current_node = {}
        elif current_node["type"] == "list":
            current_node["items"] = []
        elif current_node["type"] == "map":
            current_node["mapping"] = {}
        elif current_node["type"] == "dict":
