    if length < 4:
        raise ValueError("Length must be at least 4")
    password = ''.join(random.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-*/^&*) for _ in range(length))
    return password

