    if k > len(nums):
        return []
    result = []
    for i in range(k, len(nums)):
        window = nums[i-k:i]
        mean = sum(window) / k
        variance = sum([(x - mean)**2 for x in window]) / k
        result.append(round(variance, 3))
    return result

