def make_tar(directory: str, archive_path: str) -> str:
    """
    system-এর `tar` command চালিয়ে `directory` directory-টার একটা tar archive বানাবে, archive-টা `archive_path` file-এ লিখবে এবং `archive_path` return করবে। Archive-টা একটা uncompressed tar file, যেটাতে directory-টা আর তার ভেতরের সবকিছু থাকবে; এর member-গুলোর নাম `directory`-র শেষ component দিয়ে শুরু হবে (যেমন `docs` directory-র জন্য `docs/a.txt`)। `directory` একটা existing directory আর `archive_path` তার ভেতরে নয়।
    """
    tar_file = os.path.join(directory, archive_path)
    with tarfile.open(tar_file, 'w') as tar:
        for root, dirs, files in os.walk(directory):
            for dir in dirs:
                tar.add(os.path.join(root, dir), 'tar.gz')
    return tar_file

