def count_items(xml_text: str) -> int:
    count = 0
    stack = []
    current_level = 0
    current_item = ""
    for line in xml_text.splitlines():
        line = line.strip()
        if line.startswith("item"):
            current_level += 1
            current_item += line[1:]
            stack.append(current_item)
            current_item = ""
        elif current_level > 0:
            current_level -= 1
            current_item += line
        else:
            if current_item:
                count += len(stack)
                stack.pop()
                current_item = ""
    if current_item:
        count += len(stack)
    return count

