def count_items(xml_text: str) -> int:
    # XML ডকুমেন্ট পার্স করুন
    doc = xml.etree.ElementTree(xml_text)

    # ডকুমেন্টে কা `item` লিএমেন্টের সংখ্যা গণনা করুন
    count = 0
    for item in doc.iter():
        # যদি ট্যাগটি `item` হয়, তাহলে সেগুইলো গোনা হয়
        if item.tag == 'item':
            count += 1

    # যদি ডকুমেন্টে কোনও `item` এলিমেন্ট না থাকে, তাহলে 0 ফেরত দিন
    if count == 0:
        return 0
    else:
        return count

