def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # dp[i] - এই i-র longest bitonic subsequence-এর length
    dp = [1] * n

    # dp[0] - এই i-র longest bitonic subsequence-এর length 1
    dp[0] = 1

    # dp[1] - এই i-র longest bitonic subsequence-এর length 2
    for i in range(1, n):
        dp[i] = dp[i-1] + 1

        # যদি এই i-র longest bitonic subsequence-এ peak element থাকে, তাহলে
        # dp[i] - 1 বাড়ানো হবে
        if nums[i] > nums[i-1]:
            dp[i] = max(dp[i], dp[i-1] + 1)
        elif nums[i] < nums[i-1]:
            dp[i] = max(dp[i], dp[i-1] - 1)

    return max(dp)

