def make_tar(directory: str, archive_path: str) -> str:
    """
    একটি tar ফাইল তৈরি করুন
    """
    if not os.path.exists(directory):
        os.makedirs(directory)
    if not os.path.exists(archive_path):
        os.makedirs(archive_path)
    with tarfile(archive_path, mode='w', compresslevel=0) as tar:
        for root, dirs, files in os.walk(directory):
            for file in files:
                tar.add(os.path.join(root, file), "tar")
    return tar.tarinfo

