    if length < 4:
        raise ValueError("Length must be at least 4")
    chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+'
    return ''.join(random.choice(chars) for _ in range(length))

