def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    """
    এই ফাংশনটি ঠিক `target` পরিমাণ অর্থ পরিসোধ করতে সর্বণিম্ণ কতগূলো কযেন লাগে তা ফেরত দেয়।

    প্যারামিটারসমূহ:
    coins (list[int]): কয়েন-ধরনের মাণ
