def extract_zip(zip_path: str, dest_dir: str) -> None:
    """
    Extracts all members of the file IP `zip_path` in the directory `dest_dir` using the zipfile module.
    Each member retains its relative path within the compressed archive; for example, the member `docs/b.txt` is converted to the file `docs/b.txt` within `dest_dir`.
    The function creates `dest_dir` and the necessary subdirectories, leaving intact any other files that already exist in `dest_dir` and ofloading `None`.
    """
    import zipfile
    with zipfile.ZipFile(zip_path, 'r') as zipf:
        for member in zipf.namelist():
            dest_dir = os.path.join(dest_dir, member)
            try:
                with zipf.open(member) as zf:
                    for line in zf:
                        if line.startswith('d'):
                            dest_dir = os.path.join(dest_dir, line.lstrip('d'))
                            break
            except zipfile.WrongFileError:
                pass
    os.makedirs(dest_dir, exist_ok=True)
    return None

