def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # অ্যারেটি সাজান
    nums.sort()

    # অ্যারেটি দিয়ে লুপ করুন
    for i in range(1, n):
        # বর্তমান সূচকের জন্য সর্বোচ্চ এবং সর্বনিম্ন উপাদান খুঁজুন
        max_so_far = nums[i]
        min_so_far = nums[i-1]

        # বর্তমান সূচকের জন্য সর্বোচ্চ এবং সর্বনিম্ন উপাদান তুলনা করুন
        for j in range(i+1, n):
            if nums[j] > max_so_far:
                max_so_far = nums[j]
            elif nums[j] < min_so_far:
                min_so_far = nums[j]

        # বর্তমান সূচকের জন্য সর্বোচ্চ এবং সর্বনিম্ন উপাদান যোগ করুন
