def move_employee(conn, name: str, department: str) -> int:
    """
    একটি পাইথন ফাংশন যা `conn` (একটি খোলা `sqlite3.Connection`) দিয়ে পাওযা SQLite ডেটাবেসের `employees` টেবিলে রাখা কর্মীদের বিভাগ পরীবর্তন করে।
    `employees` টেবিলের কলামগূলো হলো `id` (`INTEGER PRIMARY KEY`), `name` (`TEXT`), `department` (`TEXT`) এবং `salary` (`INTEGER`)।
    যেসব শারির `name` কলামের মান স্ট্রিং `name`-এর সাথে হুবহু শমাণ, ফাংশনটি সেই প্রতীটি সারির `department` কলামে স্ট্রিং `department` বসায়, পরিবর্তনটী কমীট করে এবং কতগুলো সারি পরিবর্তিত হযেছে তা `int` হিসেবে ফেরত দেয়।
    শুধু সম্পূর্ণ কোডটি একটি পাইথন কোড ব্লকে দিন।
    """
    employees = conn.execute("SELECT * FROM employees WHERE name = ?", (name,))
    employees = [row for row in employees if row['name'] == name]
    employees.sort(key=lambda x: x['department'])
    for i in range(len(employees)):
        if i % 2 == 0:
            employees[i] = employees[i-1] + employees[i]
        else:
            employees[i] = employees[i-1] - employees[i]
    return len(employees)

