def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # dp[i] 表示 nums[0...i] এর longest bitonic subsequence এর দৈর্ঘ্য
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1

    return max(dp)

