def longest_bitonic_length(nums: list[int]) -> int:
    if len(nums) == 0:
        return 0

    def get_longest_bitonic_length(start, end):
        if start == end:
            return 1

        left_length = get_longest_bitonic_length(start, end - 1)
        right_length = get_longest_bitonic_length(start + 1, end)

        if right_length > left_length:
            return right_length + 1
        else:
            return left_length + 1

    return get_longest_bitonic_length(0, len(nums) - 1)

