def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    def is_valid(row: int, col: int) -> bool:
        return 0 <= row < n and 0 <= col < n and (row, col) not in blocked

    def solve(row: int, col: int) -> int:
        if row == n:
            return 1
        if is_valid(row, col) and (row, col) not in blocked:
            return solve(row + 1, col) + solve(row, col + 1) + solve(row + 1, col + 1)
        return 0

    return solve(0, 0)

