def log_page_view(log_path: str, timestamp: str, method: str, path: str, status: int) -> None:
    """
    এই ফাংশনটি পাথ `log_path`-এ থাকা টেক্সট ফাইলের শেষে একটি পেজ রিকোয়েস্টের বিবরণসহ একটি লাইন যুক্ত করে; ফাইলটি না থাকলে তৈরি করে এবং আগের বিষয়বস্তু অক্ষুণ্ণ রাখে। লাইনের বিন্যাস `<timestamp> <method> <path> <status>`; এখানে `<timestamp>`, `<method>`, `<path>` ও `<status>` যথাক্রমে আর্গুমেন্ট `timestamp`, `method`, `path` ও `status`-এর মান বোঝায়; `status` একটি `int` এবং দশমিক পদ্ধতিতে লেখা হয়। লাইনটি UTF-8-এ লেখা হয় এবং একটিমাত্র নিউলাইন অক্ষর `\n` দিয়ে শেষ হয়। ফাংশনটি `None` ফেরত দেয়।

    শুধুমাত্র সম্পূর্ণ কোডটি একটি পাইথন কোড ব্লকে দিন।
    """
    with open(log_path, 'r') as log_file:
        lines = log_file.readlines()

    if len(lines) == 0:
        with open(log_path, 'w') as log_file:
            log_file.write(f'<timestamp> <method> <path> <status> \n')
        return

    if len(lines) > 1:
        for i in range(1, len(lines)):
            if lines[i].startswith(timestamp):
                log_file.write(f'<timestamp> <method> <path> <status> \n')
            elif lines[i].startswith(method):
                log_file.write(f'<timestamp> <method> <path> <status> \n')
            elif lines[i].startswith(path):
                log_file.write(f'<timestamp> <method> <path> <status> \n')
            elif lines[i].startswith(status):
                log_file.write(f'<timestamp> <method> <path> <status> \n')
            else:
                log_file.write(f'<timestamp> <method> <path> <status> \n')
    else:
        log_file.write(f'<timestamp> <method> <path> <status> \n')

