    visited.add((0, 0))
    while queue:
        x, y, path = queue.pop(0)
        if grid[x][y] == 'E':
            return path
        neighbors = [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]
        for nx, ny in neighbors:
