def shortest_path_one_break(grid: list[str]) -> int:
    m = len(grid)
    n = len(grid[0])
    queue = [(0, 0, 0)]
    visited = set()
    while queue:
        x, y, moves = queue.pop(0)
        if (x, y) == (m - 1, n - 1):
            return moves
        visited.add((x, y))
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == '.' and (nx, ny) not in visited:
                queue.append((nx, ny, moves + 1))
    return -1

