        edges: প্রান্তের তালিকা

    Returns:
        সব ব্রিজ
    """
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    bridges = []

    for i in range(n):
        if not visited[i]:
            visited[i] = True
            stack = [i]
            while stack:
                u = stack.pop()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
                        bridges.append((u, v))

    return bridges

