def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    """
    `n` by `n` chessboard e `n` ta queen emonbhabe boshanor upayer shonkha return korbe, jate kono duto queen eke oporke attack na kore (kono duto ek-i row, ek-i column ba ek-i diagonal e na thake) ebong kono queen `blocked` e thaka kono square e na thake. Square gulo `(row, column)` pair, jar index 0 theke shuru (0-based). Kono blocked square shudhu tate queen boshano nishiddho kore; eta tar bhetor diye queen der attack atkay na. Board er baire thaka `blocked` er entry ignore kora hobe. `n` soman 0 hole thik ekta placement (empty placement) ache, tai result 1.

    Shudhu puro code ta ekta Python code block-e din.
    """
    board = [[0 for _ in range(n)] for _ in range(n)]
    for row, col in blocked:
        board[row][col] = 1
    count = 0
    for row in range(n):
        for col in range(n):
            if board[row][col] == 1:
                count += 1
                board[row][col] = 0
    return count

