    """
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    bridges = []

    for u, v in edges:
        if u in visited or v in visited:
            continue

        visited.add(u)
        visited.add(v)
        bridges.append((u, v))

