            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)

    in_degree = {}
    for a in graph:
        in_degree[a] = 0

    for a, b in pairs:
        in_degree[a] += 1

    queue = []
    for a in graph:
