def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    visited = [False] * n
    bridges = []
    for i in range(n):
        if not visited[i]:
            visited[i] = True
            for neighbor in graph[i]:
                if not visited[neighbor]:
                    bridges.append((i, neighbor))
    bridges.sort()
    return bridges

