def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    bins = []
    bins.append([size, size + size] for size in sizes)
    bins.sort(key=lambda x: x[0], reverse=True)
    for size, bin_size in bins:
        if bin_size > capacity:
            raise ValueError("Capacity exceeded")
        bins.append([size, bin_size])
    return bins

