def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    bins = []
    bins.append([size for size in sizes if size <= capacity])
    remaining = capacity - sum(sizes)
    for size in sizes:
        if size <= remaining:
            bins.append([size, size])
            remaining -= size
        else:
            bins.append([size, remaining])
            remaining = 0
    return bins

