    """
    একটি ython ফাংশন যা `n` কাজ নম্বরকে `0` থেকে `n - 1` পর্যন্ত সাজায়।
    প্রতিটি টুপল `(a, b)` যেখানে `pairs` তালিকায় রয়েছে, তা বোঝায় যে কাজ `a` কাজ `b` এর আগে আসবে, এবং একই জোড়া একাধিকবার থাকতে পারে।
    ফাংশনটি একটি তালিকা রিটার্ন করে যা সব কাজ এক এক করে আসবে এবং সব শর্ত পূরণ করবে;
    সব বৈধ অর্ডারে, এটি সবচেয়ে ছোটটি রিটার্ন করবে (যা তালিকার উপাদানগুলো তুলনা করে)।
    যদি শর্তে একটি চক্র থাকে (একটি জোড়া `(a, a)` কাজ হিসেবে গণনা হয়), তবে এটি খালি তালিকা রিটার্ন করবে;
    যদি `n` 0 হয়, তবে খালি তালিকা রিটার্ন করবে।
    """
    # কাজগুলো সাজানোর জন্য একটি সাজানো তালিকা তৈরি করুন
    tasks = [0] * (n + 1)
    for pair in pairs:
        tasks[pair[0]] += 1
        tasks[pair[1]] += 1
    # কাজগুলো সাজান
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            if tasks[i] > tasks[j]:
                tasks[i], tasks[j] = tasks[j], tasks[i]
    # সাজানো তালিকা ফেরত দিন
    return [tasks[i] for i in range(n)]

