    for a, b in pairs:
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)

    in_degree = {}
    for a in graph:
        in_degree[a] = 0

    for a, b in pairs:
        in_degree[a] += 1

    queue = []
    for a in graph:
        if a not in in_degree:
            queue.append(a)
        elif in_degree[a] == 0:
            queue.append(a)

    result = []
    while queue:
        a = queue.pop(0)
        result.append(a)
        for neighbor in graph[a]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

