    """
    এই ফাংশনটি একটি সিস্টেমের সমতুল্য সমীকরণ সমাধান করে। প্রতিটি টুপল `(r, m)` এর মধ্যে একটি বোঝায় যে, অজানা পূর্ণসংখ্যা `x` অবশ্যই `x % m == r % m` শর্ত পূরণ করতে হবে, যেখানে `m` একটি ধনাত্মক পূর্ণসংখ্যা; `r` নেতিবাচক বা বড় হতে পারে, এবং মডিউলের জোড়াগুলো একে অপরকে সমদ্বিখণ্ডিত করতে পারে না। যদি সিস্টেমটি একটি সমাধান থাকে, তবে ফাংশনটি একটি টুপল `(x, L)` রিটার্ন করে, যেখানে `L` হলো সব মডিউলের লঘিষ্ঠ সাধারণ গুণিতক এবং `x` হলো অনন্য সমাধান যা `0 <= x < L`। যদি সিস্টেমটি কোনও সমাধান না থাকে, তবে এটি `None` রিটার্ন করে।
    """
    if len(congruences) == 0:
        return (0, 1)

    # প্রতিটি সমীকরণকে একটি টুপলের সাথে সংযুক্ত করুন
    for i in range(len(congruences)):
        for j in range(len(congruences)):
            if i != j:
                congruences[i] = (congruences[i][0], congruences[i][1])
                congruences[j] = (congruences[j][0], congruences[j][1])

    # সব সমীকরণ সমাধান করুন
    for i in range(len(congruences)):
        for j in range(len(congruences)):
            if i != j:
                congruences[i] = (congruences[i][0], congruences[i][1])
                congruences[j] = (congruences[j][0], congruences[j][1])

    # লঘিষ্ঠ সাধারণ গুণিতক হিসাব করুন
    lcm = 1
    for i in congruences:
        lcm = lcm * congruences[i][0]
        lcm = lcm // congruences[i][1]

    # অনন্য সমাধান হিসাব করুন
    x = lcm
    for i in congruences:
        x = lcm * congruences[i][0]
        x = lcm // congruences[i][1]

    return (x, lcm)

