def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    stack = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] > 0:
                stack.append((i, j))
    while stack:
        r, c = stack.pop()
        neighbors = []
        for i in range(r - 1, r + 2):
            for j in range(c - 1, c + 2):
                if grid[i][j] > 0:
                    neighbors.append((i, j))
        if len(neighbors) > 3:
            grid[r][c] = 0
        else:
            grid[r][c] = 1
            for i in range(r - 1, r + 2):
                for j in range(c - 1, c + 2):
                    if grid[i][j] > 0:
                        grid[i][j] = 0
    return grid

