    """
    এই ফাংশনটি একটি গ্রাফের মধ্যে shortest paths এর সংখ্যা গণনা করে, যেখানে গ্রাফটি নোড 0 থেকে n-1 এর মধ্যে, এবং গ্রাফের edges হলো (u, v) জোড়া।

    যদি গ্রাফে edges এর একই জোড়া একাধিক বার থাকে, তবে সেটি একটি একক সংযোগ হিসেবে গণনা করা হয়।

    যদি source এবং target নোড একই হয়, তবে ফলাফল 1।

    এই ফাংশনটি কেবল একটি Python কোড ব্লক রিটার্ন করবে।
    """
    if source == target:
        return 1

    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append(v)

    queue = [(source, 0)]
    visited = set()

    while queue:
        node, dist = queue.pop(0)

        if node == target:
            return dist

        visited.add(node)

        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, dist + 1))

    return 0

