def download_text(url: str, attempts: int = 3) -> str | None:
    """
    `download_text` ফাংশনটি `requests` লাইব্রেরি ব্যবহার করে kore ekta text document download korbe।
    ফাংশনটি `url` এ GET request pathabe ebong response body r text `str` hishebe return korbe।
    Response er status code 404 hole `None` return korbe; 400 ba tar beshi onno jekono status code er jonno `requests.HTTPError` raise korbe।
    Request pathate giye `requests.ConnectionError` raise hole function ta request ta abar pathabe; mot sorbocho `attempts` bar request pathano hobe, ar shobgulotei `requests.ConnectionError` raise hole sorboshesh sei error ta raise korbe।
    Kono response pawa gele tar status code ja-i hok, request ar retry kora hobe na।
    """
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 404:
            return "404: Not Found"
        elif e.response.status_code == 400:
            return "400: Bad Request"
        elif e.response.status_code == 500:
            return "500: Internal Server Error"
        else:
            return "500: Internal Server Error"

