def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    """
    এই ফাংশনটি একটি সিম্পল সিস্টেমের সমাধান খুঁজে বের করে।
    প্রতিটি tuple (r, m) মানে x এর কলামের মান m দ্বারা বিভাজ্য, যেখানে r হলো কলামের মান।
    r এর মান যদি m দ্বারা বিভাজ্য হয়, তবে x এর মান m দ্বারা বিভাজ্য হবে।
    যদি সিস্টেমের সমাধান থাকে, তবে এটি একটি tuple (x, L) রিটার্ন করে, যেখানে x হলো সমাধান এবং L হলো সর্বনিম্ন ভিউমুলো।
    যদি সিস্টেমের সমাধান না থাকে, তবে এটি None রিটার্ন করে।
    একটি খালি তালিকা (0, 1) এর জন্য, এটি কেবল (0, 1) রিটার্ন করে।
    """
    if len(congruences) == 0:
        return (0, 1)
    if len(congruences) == 1:
        return (congruences[0][0], congruences[0][1])
    if len(congruences) == 2:
        x, L = congruences[0][0], congruences[0][1]
        for r in congruences[1]:
            if r % L != congruences[1][0] % L:
                return None
        return (x, L)
    return None

