def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    """
    `sizes` er positive integer item size gulo ke `capacity` khomotar bin e first-fit decreasing strategy te pack korbe: item gulo size er descending order e process kora hoy, ar protita item shobcheye age khola emon bin e rakha hoy jekhane seta ekhono fit kore (oi bin er total ar item er size er jogfol `capacity` chharay na); emon kono bin na thakle item ta r jonno notun bin khola hoy. Function ta bin gulor list tader kholar order e return korbe; protita bin holo item gulo tate je order e rakha hoyeche sei order e tar item size gulor list. Kono item `capacity` er cheye boro hole `ValueError` raise korbe. `sizes` empty hole result empty list.
    """
    bins = []
    for size in sizes:
        if size <= capacity:
            bins.append([size])
        else:
            bins.append([size, size])
    return bins

