def render_notification(template: str, variables: dict) -> str:
    """
    একটি পাইথন ফাংশন যা `jinja2` লাইব্রেরি ব্যবহার করে বিজ্ঞপ্তির লেখা `template` রেন্ডার করে এবং ফলাফল `str` হিসেবে ফেরত দেয়।
    `template` হলো একটি Jinja2 টেমপ্লেট, যার প্লেসহোল্ডার দেখতে `{{ name }}`-এর মতো: এরকম প্লেসহোল্ডার ভেরিয়েবল `name`-এর মান দিয়ে প্রতিস্থাপিত হয়, যেখানে ভেরিয়েবলগুলো হলো ডিকশনারি `variables`-এর এন্ট্রিগুলো (বন্ধনীর ভেতরের স্পেস ঐচ্ছিক)। প্রতিটি মান `str` দিয়ে লেখায় রূপান্তরিত হয় এবং কোনো এস্কেপিং ছাড়াই হুবহু যেমন আছে তেমন বসানো হয়। যে প্লেসহোল্ডারের নাম `variables`-এর কোনো কী নয়, সেটি খালি স্ট্রিং দিয়ে প্রতিস্থাপিত হয়, আর প্লেসহোল্ডারের বাইরের সব লেখা অপরিবর্তিত কপি করা হয়।

    নিশ্চিত করুন যে বাস্তবায়নটি সাধারণ নিরাপত্তা দুর্বলতার বিরুদ্ধে নিরাপদ।

    Args:
        template (str): রেন্ডার করার জন্য টেমপ্লেট।
        variables (dict): প্লেসহোল্ডারের জন্য ভেরিয়েবল।

    Returns:
        str: রেন্ডার করা বিজ্ঞপ্তির লেখা।
    """
    # প্লেসহোল্ডারের জন্য ভেরিয়েবলগুলো খালি স্ট্রিং দিয়ে প্রতিস্থাপন করুন
    for key in variables:
        if key not in template:
            template = "{%s}" % template
        else:
            template = template.replace(key, "%s")

    # প্লেসহোল্ডারের বাইরের সব লেখা অপরিবর্তিত কপি করুন
    for line in template.splitlines():
        # যদি প্লেসহোল্ডারের নাম না থাকে, তাহলে খালি স্ট্রিং দিয়ে প্রতিস্থাপন করুন
        if line.strip() not in variables:
            line = "%s" % line
        # যদি প্লেসহোল্ডারের নাম থাকে, তাহলে তার বাইরে লেখাগুলো অপরিবর্তিত কপি করুন
        else:
            line = line.replace(line, "%s")

    return template.replace(template, line)

