import requests

def download_text(url: str, attempts: int = 3) -> str | None:
    """
    একটি টেক্সট ডকুমেন্ট ডাউনলোড করে।

    :param url: ডাউনলোড করার জন্য URL
    :param attempts: কতবার অনুরোধ করা হবে
    :return: ডাউনলোড করা টেক্সট বা None
    """
    for _ in range(attempts):
        try:
            response = requests.get(url)
            if response.status_code == 404:
                return None
            elif response.status_code >= 400:
                raise requests.HTTPError(400)
            else:
                return response.text
        except requests.ConnectionError:
            if attempts > 0:
                response = requests.get(url)
                if response.status_code == 404:
                    return None
                elif response.status_code >= 400:
                    raise requests.HTTPError(400)
                else:
                    return response.text
        except requests.HTTPError:
            raise requests.HTTPError(400)
    return None

