def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    """
    এই ফাংশনটি একটি স্ট্রিং `source` কে `target` স্ট্রিংয়ে রূপান্তর করার জন্য এক-করের অপারেশনগুলির সর্বনিম্ন খরচ ফেরত দেয়।
    এই ফাংশনটি নিম্নলিখিত অপারেশনগুলি ব্যবহার করে:
    - Insert: একটি অক্ষর যোগ করা
    - Delete: একটি অক্ষর সরানো
    - Replace: একটি অক্ষর অন্য অক্ষর দিয়ে প্রতিস্থাপন করা
    """
    n = len(source)
    m = len(target)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                dp[i][j] = j * insert_cost
            elif i == 1:
                dp[i][j] = insert_cost * delete_cost
            elif j == 0:
                dp[i][j] = insert_cost * replace_cost
            elif i == 1 and j == 1:
                dp[i][j] = delete_cost * insert_cost
            elif i == 1 and j == 0:
                dp[i][j] = delete_cost * replace_cost
            elif i == 0 and j == 1:
                dp[i][j] = insert_cost * replace_cost
            elif i == 0 and j == 0:
                dp[i][j] = insert_cost * delete_cost
    return dp[n][m]

