def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    """
    এই ফাংশনটি একটি স্ট্রিং `source` কে একটি স্ট্রিং `target` এ রূপান্তর করার জন্য ন্যূনতম খরচ ফেরত দেয়, যা এক-কাচের অপারেশন ব্যবহার করে:
    - ইনসার্ট খরচ: `insert_cost`
    - ডিলিট খরচ: `delete_cost`
    - প্রতিস্থাপন খরচ: `replace_cost`
    """
    if source == target:
        return 0

    # স্ট্রিংগুলির দৈর্ঘ্য তুলনা করুন
    if len(source) != len(target):
        return float('inf')

    # স্ট্রিংগুলির দৈর্ঘ্য তুলনা করুন
    if len(source) > len(target):
        return delete_cost + weighted_edit_cost(target, source, insert_cost, replace_cost, delete_cost)
    else:
