            for arrangement in generate_arrangements(current_arrangement + [a], remaining_guests[:i] + remaining_guests[i+1:]):
                if not is_conflict(a, i):
                    arrangements.append(arrangement)
        return arrangements

    return generate_arrangements([], guests)

