def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    """
    এই ফাংশনটি তালিকা `guests`-এর (ভিন্ন ভিন্ন নাম) সব অতিথিকে এক সারিতে এমনভাবে ববসানোর সববগুলো উপায় ফেরত দেয়, যাতে পাশাপাশি ববসা কোনোনো দুই অতিথি `conflicts`-এ তালিকাভুক্ত কোনো জোড়া না হয়।
    """
    def is_conflict(a: str, b: str) -> bool:
        return a in guests and b in guests and guests.index(a) == guests.index(b)

    def generate_arrangements(current_arrangement: list[str], remaining_guests: list[str]):
        if not remaining_guests:
            return current_arrangement

        for i in range(len(remaining_guests)):
            if is_conflict(remaining_guests[i], current_arrangement[-1]):
                continue

            new_arrangement = current_arrangement + [remaining_guests[i]]
            new_remaining_guests = remaining_guests[:i] + remaining_guests[i+1:]

            arrangements = generate_arrangements(new_arrangement, new_remaining_guests)
            return arrangements

    return generate_arrangements([], guests)

