    if not isinstance(expression, str):
        raise ValueError("expression must be a string")
    if not isinstance(record, dict):
        raise ValueError("record must be a dictionary")
    if not expression:
        return False
    if not isinstance(expression, (str, int, float, bool)):
        raise ValueError("expression must be a string, integer, float, or boolean")
    if expression.startswith(" "):
        return False
    if expression.endswith(" "):
        return False
    if expression.startswith("="):
        return record.get("value") == expression
    if expression.endswith("="):
        return record.get("value") == expression
    if expression.startswith("-"):
        return record.get("value") >= expression
    if expression.endswith("-"):
        return record.get("value") <= expression
    if expression.startswith("=="):
        return record.get("value") == expression
    if expression.endswith("!="):
        return record.get("value") != expression
    if expression.startswith("<>"):
        return record.get("value") < expression
