def tidy_punctuation(text: str) -> str:
    """
    এই ফাংশনটি নির্দিষ্ট ফর্মে একটি স্ট্রিংয়ের পংক্তি পরিষ্কার করে।

    পদ্ধতি 1: প্রতিটি স্পেসের সেকশনকে একটি একক স্পেস দিয়ে প্রতিস্থাপন করে এবং স্পেসের শুরু ও শেষের স্পেসগুলো সরিয়ে দেয়।

    পদ্ধতি 2: প্রতিটি স্পেসের সেকশন থেকে সরাসরি একটি স্পেসের পরে থাকা স্পেসগুলো সরিয়ে দেয়।

    পদ্ধতি 3: প্রতিটি স্পেসের সেকশন থেকে সরাসরি একটি স্পেসের পরে থাকা স্পেসের পরে একটি স্পেস যোগ করে।

    পদ্ধতি 4: প্রথম অক্ষর এবং তার পরে থাকা সব অক্ষরকে বড় অক্ষরে রূপান্তর করে।

    আউটপুট:
    """
    cleaned_text = ""
    for i in range(len(text)):
        if i > 0 and text[i] == ' ':
            cleaned_text += ' '
        elif i == 0 and text[i] == ' ':
            cleaned_text += ' '
        elif i == len(text) - 1 and text[i] == ' ':
            cleaned_text += ' '
        elif text[i] in [' ', '!', '?', ':']:
            cleaned_text += ' '
        else:
            cleaned_text += text[i]
    return cleaned_text

