def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    if n == 0:
        return []

    # বাইরের বলয় তৈরি করুন
    outer_ring = []
    for i in range(n):
        outer_ring.append(matrix[i][n - 1:n - 1 + k])

    # ভেতরের বলয় তৈরি করুন
    inner_ring = []
    for i in range(n - 1, n - 1 - k, -1):
        inner_ring.append(matrix[i][n - 1 - k:n - 1 - k + 1])

    # নতুন ম্যাট্রিক্স তৈরি করুন
    new_matrix = []
    for i in range(n):
        new_row = []
        for j in range(n):
            new_row.append(inner_ring[j][i])
        new_matrix.append(new_row)

    return new_matrix

