def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    """
    এই ফাংশনটি একটি নির্দিষ্ট দিনের জন্য অবাধ স্থানগুলি ফেরত দেয়।
    """
    free_slots = []
    for start, end in busy:
        if start >= end:
            continue
        start_end = max(start, end)
        if start_end - start >= min_len:
            free_slots.append((start, end))
    return free_slots

