def render_mail_merge(template: str, recipients: list[dict]) -> list[str]:
    """
    একটি Jinja2 টেমপ্লেট স্ট্রিং `template` এবং `recipients` এর তালিকা গ্রহণ করে, এবং `jinja2` লাইব্রেরি ব্যবহার করে প্রতিটি প্রাপকের জন্য একটি ব্যক্তিগতকৃত টেক্সট লিখে। এটি একটি তালিকা রিটার্ন করে যার প্রতিটি উপাদানে একটি স্ট্রিং থাকে, একই ক্রমে, যেখানে প্রাপকের টেক্সট `template` টেমপ্লেটটি সেই প্রাপকের ডিকশনারির মান হিসেবে ব্যবহার করে। একটি placeholder যেমন `{{ first_name }}` এর পরিবর্তে প্রাপকের ভেরিয়েবলের মান ব্যবহৃত হয়। প্রতিটি মানকে টেক্সটে রূপান্তর করে এবং `str` টাইপ ব্যবহার করে, যেখানে কোনও স্পেসের ভিতরে থাকা ব্র্যাকেটের পরে। যদি প্রাপকের ডিকশনারিতে কোনও কী না থাকে, তাহলে placeholder এর নাম খালি স্ট্রিং, এবং টেক্সটের বাইরে থাকা সমস্ত মান অপরিবর্তিত থাকে। যদি প্রাপকের তালিকা খালি হয়, তাহলে ফাংশনটি একটি খালি তালিকা রিটার্ন করে।
    """
    output = []
    for recipient in recipients:
        for key in recipient:
            if key in template:
                output.append(template.format(**recipient))
            else:
                output.append("")
    return output

