        # যদি রুটটি ইতিমধ্যে ডিকশনারিতে থাকে, তবে তার সাথে যোগ করুন
        if v in cost_map:
            cost_map[u].append(v)
        # যদি রুটটি ডিকশনারিতে না থাকে, তবে এটি যোগ করুন
        if v not in cost_map:
            cost_map[v] = []
        # রুটটি ডিকশনারিতে যোগ করুন
        cost_map[v].append(u)

    # ডিকশনারি থেকে সর্বনিম্ন খরচ এবং পথ খুঁজে বের করুন
    min_cost = float('inf')
    min_path = None

    for u in cost_map:
        if len(cost_map[u]) > 1:
            for v in cost_map[u]:
                if v in cost_map and len(cost_map[v]) > 1:
                    cost = cost_map[u][0] + cost_map[v][1] + w
                    if cost < min_cost:
                        min_cost = cost
                        min_path = path
        elif len(cost_map[u]) == 1:
            min_cost = cost_map[u][0]
            min_path = path

    # যদি সর্বনিম্ন খরচ এবং পথ পাওয়া যায়, তবে ফলাফল রিটার্ন করুন
    if min_cost == float('inf'):
        return None
    else:
        return (min_cost, min_path)

