def format_table(rows: list[list[str]], aligns: str) -> str:
    if len(rows) == 0:
        return ""

    # সব row-কে monospaced text হিসেবে রাউন্ড করুন
    for row in rows:
        row = "".join(row)

    # monospaced text-কে monospaced table-এ রূপান্তর করুন
    table = ""
    for row in rows:
        table += "\n"
        for cell in row:
            if aligns == "l":
                cell = cell.ljust(len(cell))
            elif aligns == "r":
                cell = cell.rjust(len(cell))
            elif aligns == "c":
                cell = cell.center(len(cell))
            table += cell + " | " + cell
        table += "\n"

    return table

