def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        if instruction == 'PUSH':
            stack.append(int(instruction.split()[1]))
        elif instruction == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif instruction == 'DUP':
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) > 1:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif instruction == 'ADD':
            if len(stack) > 1:
                stack[-1] += stack[-2]
            else:
                return None
        elif instruction == 'SUB':
            if len(stack) > 1:
                stack[-1] -= stack[-2]
            else:
                return None
        elif instruction == 'MUL':
            if len(stack) > 1:
                stack[-1] *= stack[-2]
            else:
                return None
        elif instruction == 'JMP':
            if len(stack) > 1:
                stack.pop()
            else:
                return None
        elif instruction == 'JZ':
            if len(stack) > 1:
                stack.pop()
            else:
                return None
    if len(stack) > 0:
        return None
    return stack

