def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    stack.append(0)
    while program:
        instruction = program.pop(0)
        if instruction == 'PUSH':
            stack.append(int(program.pop(0)))
        elif instruction == 'POP':
            stack.append(stack.pop(0))
        elif instruction == 'DUP':
            stack.append(stack.pop(0) + stack.pop(0))
        elif instruction == 'SWAP':
            stack.append(stack.pop(0) + stack.pop(0) + stack.pop(0))
        elif instruction == 'ADD':
            stack.append(stack.pop(0) + stack.pop(0) + stack.pop(0))
        elif instruction == 'SUB':
            stack.append(stack.pop(0) + stack.pop(0) + stack.pop(0))
        elif instruction == 'MUL':
            stack.append(stack.pop(0) + stack.pop(0) + stack.pop(0))
        elif instruction == 'JMP':
            if stack[-1] == 0:
                stack.pop()
                continue
            stack.append(stack.pop(0))
        elif instruction == 'JZ':
            if stack[-1] == 0:
                stack.pop()
                continue
            stack.append(stack.pop(0))
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(instruction)
    return stack

