def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    stack.append(0)
    while program:
        instruction = program.pop()
        if instruction == 'PUSH':
            n = int(instruction.split()[1])
            stack.append(n)
        elif instruction == 'POP':
            top = stack.pop()
            if top != 0:
                stack.append(top)
        elif instruction == 'DUP':
            top = stack.pop()
            stack.append(top * 2)
        elif instruction == 'SWAP':
            top = stack.pop()
            stack.append(top)
        elif instruction == 'ADD':
            top = stack.pop()
            stack.append(top + 2)
        elif instruction == 'SUB':
            top = stack.pop()
            stack.append(top - 2)
        elif instruction == 'MUL':
            top = stack.pop()
            stack.append(top * 2)
        elif instruction == 'JMP':
            top = stack.pop()
            if top != 0:
                stack.append(top)
        elif instruction == 'JZ':
            top = stack.pop()
            if top != 0:
                stack.append(top)
        else:
            break
    if stack[-1] != 0:
        return None
    return stack

