def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    """
    এই ফাংশনটি একটি ডিকশনারি `balances` এর একটি কপি নেয়, যেখানে প্রতিটি অপেরেশন `ops` এর সাথে প্রয়োগ করা হয়; এটি `balances` কে পরিবর্তনশীল হিসেবে বিবেচনা করে। প্রতিটি অপেরেশন একটি টুপল `('deposit', account, amount)`, `('withdraw', account, amount)`, `('transfer', source, target, amount)`, `('freeze', account)` এর মতো। একটি ট্রান্সফার অতিরিক্ত ফি 2 চার্জ করে, যা কেবল উৎস অ্যাকাউন্টকে অদৃশ্য করে দেয়। একটি অপারেশন সম্পন্ন হয়, এবং তারপর অপারেশনটি পরিবর্তিত হয়, যদি কোনও একটি শর্ত পূরণ হয়:
        - যদি অ্যাকাউন্ট নাম ডিকশনারিতে না থাকে।
        - এর পরিমাণ নেতিবাচক।
        - একটি ট্রান্সফার বা উইশওভার চার্জ করে।
        - যদি ট্রান্সফারটি সোর্স অ্যাকাউন্টকে টার্গেট অ্যাকাউন্টের সাথে মিলিয়ে যায়।
        - যদি ট্রান্সফারটি সোর্স অ্যাকাউন্টকে টার্গেট অ্যাকাউন্টের সাথে মিলিয়ে যায়।
        - যদি অপারেশন নাম কোনও পাঁচটি শর্ত পূরণ না করে।
        - যদি অ্যাকাউন্টটি ইতিমধ্যে ফ্রীজ করা হয়।
        - যদি অ্যাকাউন্টটি আনফ্রীজ করা হয়।
        - সব অ্যাকাউন্টগুলি আনফ্রীজ থাকে।
        - ফাংশনটি একটি টুপল রিটার্ন করে `(final_balances, failed)`, যেখানে `final_balances` হলো চূড়ান্ত ডিকশনারি এবং `failed` হলো `ops` এর ব্যর্থ অপেরেশনের সূচক, যা ascending ক্রমে।
    """
    final_balances = {}
    failed = []
    for op in ops:
        if op[0] not in balances:
            continue
        if balances[op[0]] < 0:
            failed.append(op[0])
        elif balances[op[0]] > 0:
            final_balances[op[0]] = balances[op[0]]
        elif balances[op[0]] == 0:
            final_balances[op[0]] = balances[op[0]]
        elif op[0] == 'transfer':
            if balances[op[1]] == 0:
                final_balances[op[1]] = balances[op[1]]
            else:
                final_balances[op[1]] += balances[op[1]]
        elif op[0] == 'withdraw':
            if balances[op[1]] == 0:
                final_balances[op[1]] = balances[op[1]]
            else:
                final_balances[op[1]] -= balances[op[1]]
        elif op[0] == 'freeze':
            if balances[op[1]] == 0:
                final_balances[op[1]] = balances[op[1]]
            else:
                final_balances[op[1]] -= balances[op[1]]
        elif op[0] == 'unfreeze':
            if balances[op[1]] == 0:
                final_balances[op[1]] = balances[op[1]]
            else:
                final_balances[op[1]] -= balances[op[1]]
        else:
            final_balances[op[0]] = balances[op[0]]
    return final_balances, failed

