def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    """
    একটি ইনপুট তালিকা সিমুলেট করে। প্রতিটি ইভেন্টের একটি tuple (kind, item, quantity)
    जिसখানে quantity একটি ধনাত্মক সংখ্যা, যেখানে kind হলো `'receive'` (ইনভেন্টরি সেই ইউনিটগুলোর জন্য 0)
    অথবা `'order'` (কাস্টমার একটি ইউনিট অর্ডার করছে)।
    সবটি আইটেমের যা কোনও ইভেন্টে উপস্থিত থাকে, তাদের ইনভেন্টরি 0 থেকে শুরু হয়।
    একটি অর্ডার পাঠানো হয়, যা ইনভেন্টরি কমায়, শুধুমাত্র যদি কোনও পূর্ববর্তী অর্ডার একই আইটেমের জন্য অপেক্ষা না করে এবং সেই আইটেমের ইনভেন্টরি >= quantity হয়।
    যদি কোনও আইটেমের ইনভেন্টরি 0 এর বেশি হয়, তাহলে অর্ডারটি অপেক্ষা করার তালিকায় যোগ হয়।
    একটি 'receive' ইভেন্ট বাড়লে, সেই আইটেমের জন্য অপেক্ষা করা অর্ডারগুলো সাজানো হয়।
    প্রথম অর্ডারটি যদি ইনভেন্টরি দ্বারা কভার হয়, তাহলে সেটি পাঠানো হয়।
    পরবর্তী অর্ডারগুলো সাজানো হয়, এবং এভাবে চলতে থাকে, যতক্ষণ না ইনভেন্টরি কভার হয়।
    অবশেষে, একটি tuple (stock, waiting) রিটার্ন করে, যেখানে stock হলো প্রতিটি আইটেমের জন্য ইনভেন্টরি, এবং waiting হলো সেই আইটেমের জন্য অপেক্ষা করা অর্ডারগুলোর তালিকা।
    """
    stock = {}
    waiting = []
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            stock[item] = 0
        elif kind == 'order':
            if stock[item] < quantity:
                stock[item] += 1
            else:
                waiting.append((item, quantity))
        else:
            stock[item] += 1
    return (stock, waiting)

