def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    queue = [(0, 0, 0)]
    visited = set()
    while queue:
        x, y, dist = queue.pop(0)
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if x + 1 < rows and y + 1 < cols and grid[x + 1][y + 1] == '1':
            queue.append((x + 1, y + 1, dist + 1))
        if x - 1 >= 0 and y - 1 >= 0 and grid[x - 1][y - 1] == '1':
            queue.append((x - 1, y - 1, dist + 1))
        if x + 1 < rows and y - 1 >= 0 and grid[x + 1][y - 1] == '1':
            queue.append((x + 1, y - 1, dist + 1))
        if x - 1 >= 0 and y + 1 < cols and grid[x - 1][y + 1] == '1':
            queue.append((x - 1, y + 1, dist + 1))
