def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for line in program:
        if line == "push":
            stack.append(int(line.strip()))
        elif line == "pop":
            if len(stack) == 0:
                return []
            stack.pop()
        elif line == "swap":
            if len(stack) == 2:
                stack[0], stack[1] = stack[1], stack[0]
    return stack

