def weighted_harmonic_mean(vals: list[float], weights: list[float]) -> float:
    if len(vals) != len(weights):
        raise ValueError("ইনপুট তালিকা এবং ওজন তালিকা সমান হতে হবে")

    if len(vals) == 0:
        return 0

    weighted_sum = 0
    for i in range(len(vals)):
        weighted_sum += vals[i] * weights[i]

    return weighted_sum / sum(weights)

