def mean_and_median(numbers: list[float]) -> tuple[float, float]:
    if len(numbers) == 0:
        return (0.0, 0.0)
    sorted_numbers = sorted(numbers)
    mean = sum(sorted_numbers) / len(sorted_numbers)
    median = sorted_numbers[len(sorted_numbers) // 2]
    return (mean, median)

