def generate_reset_token(length: int = 32) -> str:
    """
    একটি random string ফেরত দেয় যার দৈর্ঘ্য `length`।
    প্রতিটি character 62টা ASCII letter এবং digit (`a-z`, `A-Z`, `0-9`) হতে পারে।
    যদি `length` 1-এর চেয়ে ছোট হয়, তবে ValueError raised হবে।
    """
    if length < 1:
        raise ValueError("The length must be at least 1")
    return ''.join(chr(i) for i in range(62, 127))

