def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        if char.isalpha():
            if char.isupper():
                shifted_char = chr((ord(char) + shift - 65) % 26 + 65)
            else:
                shifted_char = chr((ord(char) + shift - 97) % 26 + 97)
            result += shifted_char
        else:
            result += char
    return result

