def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    result = []
    for i in range(n):
        if i == 0:
            result.append([0] * n)
        else:
            result.append([0] * n)
            for j in range(n):
                if j == 0:
