def generate_otp(digits: int = 6) -> str:
    """
    একটি পাইথন ফাংশন যা ঠিক `digits` সংখ্যক অক্ষরের একটি র‍্যান্ডম ওয়ান-টাইম কোড স্ট্রিং আকারে ফেরত দেয়; প্রতিটি অক্ষর একটি দশমিক অঙ্ক (`0-9`)।
    শুরুর শূন্যগুলো বাদ যায় না (যেমন `'004217'`)।
    যদি `digits` ১-এর চেয়ে ছোট হয়, তবে ফাংশনটি `ValueError` তোলে।
    শুধু সম্পূর্ণ কোডটি একটি পাইথন কোড ব্লকে দিন।
    """
    if digits < 1:
        raise ValueError("অবৈধ ইনপুট: `digits` অবশ্যই ১ বা তার বেশি হতে হবে।")
    return ''.join(map(str, range(digits)))

