    if expression[0] == ')':
        expression = expression[1:]
    if expression[0] == ' ':
        expression = expression[1:]

    try:
        return eval(expression)
    except ZeroDivisionError:
        raise ValueError("অজানা অপারেশন")
    except SyntaxError:
        raise ValueError("অজানা arithmetic expression")

