def log_login_attempt(log_path: str, timestamp: str, username: str, success: bool) -> None:
    """
    এই ফাংশনটি একটি স্ট্রিং `log_path` ইনপুট হিসেবে গ্রহণ করে, একটি টাইমস্ট্যাম্প হিসেবে একটি স্ট্রিং, ব্যবহারকারীর নাম হিসেবে একটি স্ট্রিং, এবং একটি বুলিয়ান `success` হিসেবে। এটি `log_login_attempt` ফাংশন ব্যবহার করে ফাইলের শেষে একটি লাইন যোগ করে। যদি ফাইলটি না থাকে, তবে এটি তৈরি করে এবং আগের কনটেন্ট অপরিবর্তিত রাখে। `timestamp` হলো লগিংয়ের তারিখ এবং সময়, এবং `username` হলো সেই ব্যবহারকারীর নাম যিনি লগইন চেষ্টা করেছেন। `success` বুলিয়ানটি নির্দেশ করে যে লগইন সফল হয়েছে বা ব্যর্থ হয়েছে। যদি লগইন সফল হয়, তবে লাইনটি হবে `<timestamp> INFO login succeeded user=<username>`, অন্যথায় `<timestamp> WARNING login failed user=<username>`. লাইনটি UTF-8 ফরম্যাটে লেখা হয় এবং শেষে একটি একক লাইনের নতুন লাইন (`\n`) দিয়ে শেষ হয়। ফাংশনটি `None` রিটার্ন করে।
    """
    with open(log_path, "a") as f:
        f.write(f"{timestamp}\n\n{username} লগইন চেষ্টা করেছে।")
        if success:
            f.write(f"{timestamp}\n\n{username} সফল লগইন হয়েছে।")
        else:
            f.write(f"{timestamp}\n\n{username} লগইন ব্যর্থ হয়েছে।")

