    if len(congruences) == 0:
        return (0, 1)

    for congruence in congruences:
        x, L = congruence
        if x % L == congruence[0] % L:
            r = x % L
            m = x % r
            if r < m:
                r = m
            if r % L == congruence[0] % L:
                return (x, L)
            else:
                return None
    return None

