def reset_password(email: str, new_password: str, set_password) -> bool:
    """
    একটি অ্যাকাউন্টের পাসওয়ার্ড বদলায় এবং স্ট্যান্ডার্ড `logging` মডিউল ব্যবহার করে ফলাফল লগ করে।
    `new_password`-এ 8টির কম অক্ষর থাকলে ফাংশনটি কিছুই বদলায় না: এটি `WARNING` স্তরে একটি লগ রেকর্ড তৈরি করে, যার বার্তায় `email`-এর মান এবং `rejected` শব্দটি থাকে, এবং `ValueError` তোলে। অন্যথায় ফাংশনটি `set_password(email, new_password)` কল করে — এটি কলারের দেওয়া একটি ফাংশন, যা ওই ইমেইল ঠিকানার অ্যাকাউন্টের পাসওয়ার্ড বদলানো হলে `True` এবং এমন কোনো অ্যাকাউন্ট না থাকলে `False` ফেরত দেয় — এবং সেই মানটি `bool` হিসেবে ফেরত দেয়। ওই কলের পর ফাংশনটি `INFO` স্তরে একটি লগ রেকর্ড তৈরি করে, যার বার্তায় `email`-এর মান থাকে, এবং `set_password` `True` ফেরত দিলে `updated` শব্দটি অথবা `False` ফেরত দিলে `unknown` শব্দটি থাকে।

    শুধু সম্পূর্ণ কোডটি একটি পাইথন কোড ব্লকে দিন।
    """
    if len(new_password) < 8:
        return False
    try:
        new_password = new_password.replace(' ', '')
        if new_password.islower():
            return False
        else:
            return True
    except ValueError:
        return False

