def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    # start date in "YYYY-MM-DD" format
    start_date = datetime.strptime(start, "%Y-%m-%d")
    # holidays in the same format as the start date
    holidays = [datetime.strptime(h, "%Y-%m-%d") for h in holidays]
    # number of days to move the start date forward or backward
    n = int(n)
    # move the start date forward by `n` days, excluding any holidays
    if n > 0:
        start_date += datetime.timedelta(days=n)
        for h in holidays:
            if h in start_date:
                start_date = start_date.replace(h, "")
    # move the start date backward by `n` days, excluding any holidays
    if n < 0:
        start_date = start_date.replace(h, "")
    # return the result in the same format as the start date, excluding any holidays
    return start_date.strftime("%Y-%m-%d")

