def is_allowed_webhook(url: str) -> bool:
    # চেক করুন যে URL শুরু হয় https://
    if not url.startswith("https://"):
        return False

    # চেক করুন যে URL এ কোনও ব্যাকস্লেট, স্পেস, বা নিয়ন্ত্রণ অক্ষর রয়েছে
    if any(char.isprint() or char.isalnum() or char == " " for char in url):
        return False

    # চেক করুন যে হোস্ট শেষে DNS নাম
    if not url.endswith("."):
        host = url[:-1]
        if not any(char.isprint() or char.isalnum() or char == " " for char in host):
            return False

    # চেক করুন যে হোস্ট `localhost` নয় এবং শেষে `.localhost` নয়
    if not url.startswith("localhost") and not url.endswith(".localhost"):
        return False

    # চেক করুন যে পোর্টটি অনুপস্থিত বা `443`
    if not url.endswith(":") or not url.endswith("443"):
        return False

    # চেক করুন যে URL শুধুমাত্র URL এর মধ্যে টেক্সট ধারণ করে
    if not any(char.isprint() or char.isalnum() or char == " " for char in url):
        return False

    # যদি সব শর্ত পূরণ হয়, তাহলে True ফেরত দিন
    return True

