```python
def shortest_path_one_break(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    start = (0, 0)
    end = (rows - 1, cols - 1)
    queue = [(start, 0)]
    visited = set()
    while queue:
        (row, col) = queue.pop(0)
        if (row, col) == end:
            return 0
        if (row, col) in visited:
            continue
        visited.add((row, col))
        if grid[row][col] == '#':
            queue.append((row, col, 1))
        elif grid[row][col] == '.':
            queue.append((row, col, 0))
    return -1
```

